-- Disposable end-to-end fixtures; no invitations, production changes or stock persist.
begin;
set local request.jwt.claims='{"sub":"2fb0bab9-a296-499c-80fe-fdb87f1127ce","role":"authenticated"}';
do $qa$
declare adrian uuid:=auth.uid(); don uuid; guy uuid; op uuid; unitid uuid; assetid uuid; partid uuid; loc uuid; loc2 uuid; vendor uuid; obs uuid; wo uuid; req uuid; po uuid; line uuid; result jsonb; n numeric; amount numeric;
begin
 select id into strict don from public.profiles where email='don@ruelconcreteltd.com' and role='unit_supervisor' and corporate_manager_id=adrian;
 select id into strict guy from public.profiles where personnel_category='ceo' and active;
 select id into strict op from public.profiles where full_name='[MOC] Casey White';
 select id into strict unitid from public.business_units where code='CONC-PR';
 select id into strict assetid from public.assets where business_unit_id=unitid and asset_code like 'MOC-%' limit 1;
 update public.profiles set corporate_manager_id=don where id=op;
 insert into public.user_unit_access(user_id,business_unit_id,access_role,can_edit,can_approve) values(op,unitid,'operator',false,false) on conflict(user_id,business_unit_id) do update set can_edit=false,can_approve=false;
 select id into strict vendor from public.vendors where name like '[MOC]%' limit 1;
 insert into public.parts(part_number,description,unit_of_measure,standard_cost) values('[QA rollback] purchase test','Transactional fixture','ea',100) returning id into partid;
 select id into strict loc from public.inventory_locations where business_unit_id=unitid and active limit 1;
 insert into public.inventory_locations(name,business_unit_id,position_code) values('[QA rollback] Rack B',unitid,'QA-B-01') returning id into loc2;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',op,'role','authenticated')::text,true);
 result:=public.submit_field_observation(gen_random_uuid(),unitid,assetid,'equipment','[QA rollback] abnormal sound','normal');obs:=(result->>'observation_id')::uuid;
 if not exists(select 1 from public.field_observations where id=obs and assigned_manager_id=don) then raise exception 'Not routed to Don';end if;
 begin insert into public.work_orders(asset_id,business_unit_id,type,title) values(assetid,unitid,'corrective','Operator bypass');raise exception 'QA_OPERATOR_BYPASS';exception when others then if sqlerrm not like '%Operators submit observations%' then raise;end if;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',don,'role','authenticated')::text,true);
 perform public.request_observation_information(obs,'Please add operating condition');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',op,'role','authenticated')::text,true);
 perform public.respond_to_observation_request(obs,'Only when loaded');
 if not exists(select 1 from public.field_observations where id=obs and status='submitted') then raise exception 'Resubmission failed';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',don,'role','authenticated')::text,true);
 wo:=public.create_work_order_from_observation(obs,don,'medium',501,'[QA rollback] Client lifecycle');
 perform public.add_work_order_part_requirement(wo,partid,2,loc,'Two required');
 select id into strict req from public.work_order_part_requests where work_order_id=wo and part_id=partid;
 begin perform public.request_work_order_execution_approval(wo);raise exception 'QA_UNKNOWN_QUOTE_ACCEPTED';exception when others then if sqlerrm not like '%Confirm supplier, price and destination%' then raise;end if;end;
 insert into public.work_order_purchase_plans(request_id,preferred_vendor_id,quoted_unit_cost,supplier_confirmed) values(req,vendor,120,true);
 update public.work_orders set costs_pending=true where id=wo;
 begin perform public.request_work_order_execution_approval(wo);raise exception 'QA_PENDING_COST_ACCEPTED';exception when others then if sqlerrm not like '%Complete pending cost%' then raise;end if;end;
 update public.work_orders set costs_pending=false where id=wo;
 -- Inclusive CAD 500 boundary and cent precision.
 foreach amount in array array[500,500.01,501]::numeric[] loop
  update public.work_orders set estimated_cost=amount where id=wo;
  perform public.request_work_order_execution_approval(wo);
  if not exists(select 1 from public.work_orders where id=wo and manager_approver_id=adrian and corporate_approval_required=(amount>500)) then raise exception 'Threshold boundary failed: %',amount;end if;
 end loop;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',adrian,'role','authenticated')::text,true);
 perform public.reject_work_order_execution_approval(wo,'Revise labour details');
 if not exists(select 1 from public.notifications where user_id=don and work_order_id=wo and title='WO returned for correction') then raise exception 'Return notification missing';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',don,'role','authenticated')::text,true);
 perform public.request_work_order_execution_approval(wo);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',adrian,'role','authenticated')::text,true);
 perform public.approve_work_order_execution_manager(wo,'Reviewed');
 begin perform public.approve_work_order_execution_super_admin(wo,'Manager cannot act as CEO');raise exception 'QA_NONCEO_APPROVED';exception when others then if sqlerrm not like '%Only the designated CEO%' then raise;end if;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',guy,'role','authenticated')::text,true);
 perform public.approve_work_order_execution_super_admin(wo,'Approved');
 select l.id,l.purchase_order_id into strict line,po from public.inventory_purchase_order_lines l where work_order_part_request_id=req;
 if not exists(select 1 from public.inventory_purchase_orders where id=po and status='draft') then raise exception 'No automatic draft PO';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',don,'role','authenticated')::text,true);
 update public.inventory_purchase_orders set status='ordered' where id=po;
 select sum(quantity_on_order) into n from public.inventory_stock_summary where part_id=partid and business_unit_id=unitid;
 if n is distinct from 2::numeric then raise exception 'On order expected 2, got %',n;end if;
 perform public.receive_po_at_location(line,1,loc2);
 if not exists(select 1 from public.inventory_on_hand where part_id=partid and location_id=loc2 and quantity_on_hand=1) then raise exception 'Receipt to confirmed location failed';end if;
 begin perform public.issue_part_to_work_order(wo,partid,loc2,1,null,req,null);raise exception 'QA_PRESTART_ISSUE_ACCEPTED';exception when others then if sqlerrm not like '%Start or resume%' then raise;end if;end;
 update public.work_orders set status='in_progress',started_at=now() where id=wo;
 perform public.issue_part_to_work_order(wo,partid,loc2,1,null,req,null);
 perform public.receive_po_at_location(line,1,loc2);
 perform public.issue_part_to_work_order(wo,partid,loc2,1,null,req,null);
 if not exists(select 1 from public.inventory_purchase_orders where id=po and status='received') then raise exception 'Partial receipt did not complete';end if;
 begin perform public.receive_po_at_location(line,1,loc2);raise exception 'QA_OVERRECEIPT_ACCEPTED';exception when others then if sqlerrm not like '%not released for receiving%' and sqlerrm not like '%exceeds%' then raise;end if;end;
 perform public.return_part_from_work_order(wo,partid,loc2,1,null,req,'Unused item returned');
 if not exists(select 1 from public.work_orders where id=wo and parts_cost=120) then raise exception 'Return did not reverse original issued valuation';end if;
 perform public.issue_part_to_work_order(wo,partid,loc2,1,null,req,'Consumed after verification');
 if not exists(select 1 from public.work_orders where id=wo and parts_cost=240) then raise exception 'Incorrect WO actual parts cost';end if;
 update public.work_orders set diagnosis='Worn part confirmed',corrective_action='Replaced and tested' where id=wo;
 perform public.request_work_order_completion(wo);
 if not exists(select 1 from public.work_orders where id=wo and status='completed') then raise exception 'WO not completed';end if;
 if (select count(distinct user_id) from public.notifications where work_order_id=wo and notification_type='wo_completed' and user_id in (op,don,adrian,guy))<>4 then raise exception 'Completion recipients missing';end if;
 if not exists(select 1 from public.field_observations where id=obs and status='resolved') then raise exception 'Source observation not resolved';end if;
end $qa$;
rollback;
select 'PASS: Don -> Adrian -> Guy, 500/500.01/501, operator restriction, returns/resubmission, unknown costs, automatic draft PO, On Order, partial receipts + position, execution-only issue, actual cost, completion notifications. Fixtures rolled back.' result;
